"use client";

import {
  motion,
  useScroll,
  useSpring,
  useTransform,
} from "motion/react";

import {
  FormEvent,
  useRef,
  useState,
} from "react";

const popular = [
  "Company Registration",
  "GST Registration",
  "Trademark",
  "FSSAI",
];

export function Hero() {
  const sectionRef =
    useRef<HTMLElement>(null);

  const [query, setQuery] =
    useState("");

  const { scrollYProgress } =
    useScroll({
      target: sectionRef,
      offset: [
        "start start",
        "end start",
      ],
    });

  const progress = useSpring(
    scrollYProgress,
    {
      stiffness: 80,
      damping: 28,
      mass: 0.45,
    }
  );

  const titleY = useTransform(
    progress,
    [0, 1],
    [0, -150]
  );

  const titleScale = useTransform(
    progress,
    [0, 0.72],
    [1, 0.78]
  );

  const titleOpacity = useTransform(
    progress,
    [0, 0.73],
    [1, 0]
  );

  const blueY = useTransform(
    progress,
    [0, 1],
    [0, 180]
  );

  const waveOneY = useTransform(
    progress,
    [0, 1],
    [0, -150]
  );

  const waveTwoY = useTransform(
    progress,
    [0, 1],
    [0, -240]
  );

  const waveRotate = useTransform(
    progress,
    [0, 1],
    [-7, 4]
  );

  const glowScale = useTransform(
    progress,
    [0, 1],
    [1, 1.7]
  );

  const openServices = (
    value = ""
  ) => {
    window.dispatchEvent(
      new CustomEvent(
        "lawxygen:open-services",
        {
          detail: {
            query: value,
          },
        }
      )
    );
  };

  const submitSearch = (
    event: FormEvent
  ) => {
    event.preventDefault();

    openServices(query);
  };

  return (
    <section
      ref={sectionRef}
      className="lx2-hero"
    >
      <div className="lx2-hero-sticky">
        <motion.div
          className="lx2-hero-blue"
          style={{
            y: blueY,
          }}
        />

        <motion.div
          className="lx2-hero-glow"
          style={{
            scale: glowScale,
          }}
        />

        <div className="lx2-hero-grid" />

        <motion.div
          className="lx2-wave lx2-wave-a"
          style={{
            y: waveOneY,
            rotate: waveRotate,
          }}
        />

        <motion.div
          className="lx2-wave lx2-wave-b"
          style={{
            y: waveTwoY,
          }}
        />

        <motion.div
          className="lx2-wave lx2-wave-c"
          style={{
            y: waveOneY,
          }}
        />

        <motion.div
          className="lx2-hero-content"
          style={{
            y: titleY,
            scale: titleScale,
            opacity: titleOpacity,
          }}
        >
          <motion.div
            className="lx2-eyebrow"
            initial={{
              opacity: 0,
              y: 18,
            }}
            animate={{
              opacity: 1,
              y: 0,
            }}
            transition={{
              duration: 0.7,
              delay: 0.15,
            }}
          >
            LEGAL · TAX · COMPLIANCE · BUSINESS
          </motion.div>

          <h1>
            <span className="lx2-title-mask">
              <motion.b
                initial={{
                  y: "110%",
                }}
                animate={{
                  y: 0,
                }}
                transition={{
                  duration: 1,
                  delay: 0.08,
                  ease: [
                    0.16,
                    1,
                    0.3,
                    1,
                  ],
                }}
              >
                Business,
              </motion.b>
            </span>

            <span className="lx2-title-mask">
              <motion.b
                initial={{
                  y: "110%",
                }}
                animate={{
                  y: 0,
                }}
                transition={{
                  duration: 1,
                  delay: 0.17,
                  ease: [
                    0.16,
                    1,
                    0.3,
                    1,
                  ],
                }}
              >
                legally simplified.
              </motion.b>
            </span>
          </h1>

          <motion.p
            className="lx2-hero-text"
            initial={{
              opacity: 0,
              y: 22,
            }}
            animate={{
              opacity: 1,
              y: 0,
            }}
            transition={{
              duration: 0.8,
              delay: 0.46,
            }}
          >
            Start, manage and protect
            your business with
            registrations, taxation,
            compliance, legal
            documentation, intellectual
            property and expert support.
          </motion.p>

          <motion.form
            className="lx2-service-search"
            onSubmit={submitSearch}
            initial={{
              opacity: 0,
              y: 25,
              scale: 0.97,
            }}
            animate={{
              opacity: 1,
              y: 0,
              scale: 1,
            }}
            transition={{
              duration: 0.8,
              delay: 0.62,
            }}
          >
            <span>⌕</span>

            <input
              type="search"
              value={query}
              onChange={(event) =>
                setQuery(
                  event.target.value
                )
              }
              placeholder="What do you need help with?"
            />

            <button type="submit">
              Explore
              <b>↗</b>
            </button>
          </motion.form>

          <motion.div
            className="lx2-popular"
            initial={{
              opacity: 0,
            }}
            animate={{
              opacity: 1,
            }}
            transition={{
              duration: 0.8,
              delay: 0.82,
            }}
          >
            <span>Popular</span>

            {popular.map(
              (service) => (
                <button
                  type="button"
                  key={service}
                  onClick={() =>
                    openServices(
                      service
                    )
                  }
                >
                  {service}
                </button>
              )
            )}
          </motion.div>
        </motion.div>

        <motion.div
          className="lx2-float-chip lx2-chip-a"
          style={{
            y: waveOneY,
          }}
        >
          <i />
          Start a Business
        </motion.div>

        <motion.div
          className="lx2-float-chip lx2-chip-b"
          style={{
            y: waveTwoY,
          }}
        >
          <i />
          Protect Your Brand
        </motion.div>

        <motion.div
          className="lx2-float-chip lx2-chip-c"
          style={{
            y: waveOneY,
          }}
        >
          <i />
          Stay Compliant
        </motion.div>

        <div className="lx2-scroll">
          <span>SCROLL TO EXPLORE</span>
          <i />
        </div>
      </div>
    </section>
  );
}